import type { SpiceKernelSummary } from 'api'

// Small bodies of the SPICE Kernel Library that the Sky draws: every asteroid and comet whose kernel was generated by
// Horizons and is in the library for the ephemeris (enabled and readable), once per SPK-ID whatever the number of its
// kernels. Pure functions over the library mirror of the tab (spiceKernelsState); positions are asked of the sky API,
// which resolves them through the ephemeris chain like any minor body.

// First and last SPK-ID of the comets of the JPL Small-Body Database (1000001 to 1999999); asteroids are numbered from
// 2000001 (the original permanent scheme) and above.
const COMET_SPK_IDS = [1_000_001, 1_999_999] as const

// Readiness of a kernel the operator keeps out of the ephemeris, or that cannot be read; its body is not drawn.
const HIDDEN_READINESS: ReadonlySet<SpiceKernelSummary['readiness']> = new Set(['disabled', 'invalid', 'missing'])

// Small body of a Horizons kernel.
export interface KernelBody {
	// Canonical SBDB SPK-ID, decimal text.
	readonly spkId: string
	// Designation shown on the map, such as "161P/Hartley-IRAS".
	readonly name: string
	// Whether the SPK-ID is a comet's.
	readonly comet: boolean
}

// Whether an SBDB SPK-ID (decimal text) is a comet's.
export function isCometSpkId(spkId: string) {
	const id = Number(spkId)
	return id >= COMET_SPK_IDS[0] && id <= COMET_SPK_IDS[1]
}

// Returns the designation of a Horizons kernel: its name without the " (<SPK-ID>)" the library appends to a generated
// kernel's label, or the SPK-ID when the name is only that.
export function kernelBodyName(kernel: Pick<SpiceKernelSummary, 'name' | 'sourceRef'>) {
	const suffix = ` (${kernel.sourceRef})`
	const name = kernel.name.endsWith(suffix) ? kernel.name.slice(0, -suffix.length) : kernel.name
	return name.trim() || kernel.sourceRef || kernel.name
}

// Returns the small bodies of the Horizons, MPC, and imported element kernels of the library (each body of an element kernel,
// named by its segment), in library order, once per SPK-ID; empty without a
// snapshot.
export function kernelBodies(kernels: readonly SpiceKernelSummary[] | undefined): KernelBody[] {
	const bodies = new Map<string, KernelBody>()

	for (const kernel of kernels ?? []) {
		const spkId = kernel.sourceRef
		if (HIDDEN_READINESS.has(kernel.readiness)) continue

		if (kernel.sourceKind === 'elements') {
			for (const target of kernel.targets) {
				const id = String(target)
				if (!bodies.has(id)) bodies.set(id, { spkId: id, name: kernel.targetNames?.[target] ?? id, comet: false })
			}

			continue
		}

		if ((kernel.sourceKind !== 'horizons' && kernel.sourceKind !== 'mpc') || !spkId || bodies.has(spkId)) continue
		bodies.set(spkId, { spkId, name: kernelBodyName(kernel), comet: isCometSpkId(spkId) })
	}

	return bodies.values().toArray()
}
